def make(i, row):
    tag, prompt, opts, answer, reason = row
    target_letters=['A','B','C','D','B','C','D','A','C','B']
    aid=target_letters[i-1]
    distractors=[t for t in opts if t != answer]
    ordered=[]; di=0
    for letter in ['A','B','C','D']:
        if letter == aid: ordered.append(answer)
        else: ordered.append(distractors[di]); di += 1
    options = [{'id': chr(65+j), 'text': t} for j, t in enumerate(ordered)]
    steps = [f'讀題定位：圈出「{tag}」以及生產者、消費者、分解者、食物網、生物量或能量。', f'建立判準：{reason}', f'核對答案：選項 {aid}「{answer}」符合生態系能量流動與轉換原理。', '排除誘答：分清物質循環與能量流動、能量與生物量、食物關係與能量方向，不把熱散失當成循環。', '最後回查：確認營養階層、時間尺度、取樣條件與推論限制都和題幹一致。']
    return {'id': f'question-science-content-bd-{i}', 'subject': 'science', 'type': 'single-choice', 'prompt': prompt, 'options': options, 'knowledgeIds': ['kg-science-content-bd'], 'difficulty': 'medium', 'answer': {'value': aid, 'explanation': reason}, 'provenance': {'origin': 'original', 'license': 'All rights reserved', 'sourceUrl': URL, 'sourceLocator': '公立國中段考自然科；研究生產者、食物鏈與食物網、能量傳遞、分解者、生物量與生態資料判讀的能力方向。', 'authoringNote': '依官方課綱 KG 與公立國中公開試題能力方向獨立改寫，未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。'}, 'reviewStatus': 'draft', 'updatedAt': '2026-09-08', 'lessonId': 'lesson-science-content-bd', 'examPatternRefs': [{'url': URL, 'title': '公立國中段考自然科；僅研究題型與能力方向，未複製原題。', 'year': '114', 'subject': 'science', 'locator': '生態系中能量的流動與轉換', 'observedPattern': '能力方向研究後原創改寫', 'reuseDecision': 'pattern-only', 'status': 'recorded', 'locatorLevel': 'paper'}], 'solutionStrategy': '先辨認營養階層與取食方向，再追蹤能量取得、代謝散失與物質循環，最後用生物量資料檢查推論限制。', 'solutionSteps': steps}

for i, row in enumerate(DATA, 1):
    (OUT / f'question-science-content-bd-{i}.json').write_text(json.dumps(make(i, row), ensure_ascii=False, indent=2) + '\n')
print('rewrote', len(DATA), 'questions')
